from typing import Iterable

def equal(m1: int, n1: int, m2: int, n2: int) -> bool:
    if min(n1, n2) < 0: raise ValueError("nonnegative exponents required")
    return (m1 << n2) == (m2 << n1)

def main() -> None:
    cases: Iterable[tuple[int,int,int,int]] = [(6,4,3,3),(5,3,3,2),(-10,4,-5,3)]
    for a,m,b,n in cases:
        print(f"{a}/2^{m} = {b}/2^{n}: {equal(a,m,b,n)}")

if __name__ == "__main__": main()

def birthday(n: int) -> int:
    if n < 0: raise ValueError("n must be nonnegative")
    return n + 1

def main() -> None:
    for n in range(12):
        print(n, f"{2.0**(-n):.10f}", birthday(n))

if __name__ == "__main__": main()

def residues_mod_three(limit: int) -> list[int]:
    return [pow(2, n, 3) for n in range(limit + 1)]

def main() -> None:
    values = residues_mod_three(20)
    print(values)
    assert 0 not in values
    print("No tested power is divisible by 3; in fact the 1,2 cycle continues forever.")

if __name__ == "__main__": main()

