def dyadic_equal(m1: int, n1: int, m2: int, n2: int) -> bool:
    if n1 < 0 or n2 < 0:
        raise ValueError("exponents must be nonnegative")
    return (m1 << n2) == (m2 << n1)

def normalize_dyadic(m: int, n: int) -> tuple[int, int]:
    if n < 0: raise ValueError("n must be nonnegative")
    if m == 0: return (0, 0)
    while n > 0 and m % 2 == 0:
        m //= 2; n -= 1
    return (m, n)

def add_dyadics(a: int, m: int, b: int, n: int) -> tuple[int, int]:
    if min(m, n) < 0: raise ValueError("exponents must be nonnegative")
    k = max(m, n)
    value = (a << (k-m)) + (b << (k-n))
    if value == 0: return (0, 0)
    while k > 0 and value % 2 == 0:
        value //= 2; k -= 1
    return (value, k)

